int potenciometro = A0; // Pin de entrada analógica
int valor;             // Variable para almacenar la lectura

void setup() {
    Serial.begin(9600); // Inicializa comunicación serie a 9600 baudios
}

void loop() {
    valor = analogRead(potenciometro); // Lee el valor (0 a 1023)
    Serial.println(valor);             // Imprime el valor en el Monitor Serie
    delay(200);                        // Espera 200 milisegundos
}
